import java.io.BufferedInputStream

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun nextInt(): Int {
        var c: Int
        do {
            c = readByte()
        } while (c <= 32)

        var value = 0
        while (c > 32) {
            value = value * 10 + (c - '0'.code)
            c = readByte()
        }
        return value
    }
}

fun main() {
    val fs = FastScanner()
    val n = fs.nextInt()

    var ones = 0
    var currentGain = 0
    var maximumGain = Int.MIN_VALUE

    repeat(n) {
        val value = fs.nextInt()
        if (value == 1) ones++

        val gain = if (value == 0) 1 else -1
        currentGain = maxOf(gain, currentGain + gain)
        maximumGain = maxOf(maximumGain, currentGain)
    }

    print(ones + maximumGain)
}

import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer
import kotlin.math.max

private class FastScanner {
    private val reader = BufferedReader(InputStreamReader(System.`in`))
    private var tokenizer = StringTokenizer("")

    fun nextInt(): Int {
        while (!tokenizer.hasMoreTokens()) {
            tokenizer = StringTokenizer(reader.readLine())
        }
        return tokenizer.nextToken().toInt()
    }
}

fun main() {
    val fs = FastScanner()
    val n = fs.nextInt()

    var ones = 0
    var currentGain = 0
    var maxGain = Int.MIN_VALUE

    repeat(n) {
        val value = fs.nextInt()
        if (value == 1) ones++

        val gain = if (value == 0) 1 else -1
        currentGain = max(gain, currentGain + gain)
        maxGain = max(maxGain, currentGain)
    }

    print(ones + maxGain)
}

